  "kids.explorer.eco.tap.explainWrong": "चलता हुआ नल बहुत सारे लीटर पानी बर्बाद करता है — जब आप इसका इस्तेमाल नहीं कर रहे हों, तो इसे बंद कर दें।",
  "kids.explorer.eco.lights.prompt": "आप एक कमरे से बाहर जा रहे हैं। लाइटें चालू हैं। आप क्या करते हैं?",
