  "kids.explorer.eco.ride.explain": "छोटी यात्राओं के लिए पैदल चलना या साइकिल चलाना कोई भी प्रदूषण नहीं बनाता।",
  "kids.explorer.eco.ride.explainWrong": "कारें ईंधन इस्तेमाल करती हैं और प्रदूषण पैदा करती हैं — छोटी यात्राओं के लिए पैदल चलना या साइकिल चलाना ज़्यादा साफ़ है।",
  "kids.explorer.eco.tree.prompt": "आपका स्कूल एक बगीचा बनाने की योजना बना रहा है। इसमें क्या शामिल होना चाहिए?",
