  "kids.explorer.eco.animal.explain": "जंगली जानवर सबसे अच्छा तब करते हैं जब हम उनके घर को परेशान किए बिना उनकी प्रशंसा करें।",
  "kids.explorer.eco.animal.explainWrong": "जंगली घोंसले को छूने से माँ-बाप डरकर चले जा सकते हैं — बस देखना सबसे अच्छा है।",
